def collect(item, bucket=[]):
    """item を bucket に追加して返す。bucket 省略時は新しいリストを使う。"""
    bucket.append(item)
    return bucket


def collect_all(items):
    """items を順に collect へ渡し、最後の戻り値を返す。"""
    result = None
    for item in items:
        result = collect(item)
    return result

