import re

_NON_ALNUM = re.compile(r"[^a-z0-9]+")


def slugify(text):
    """英数字以外をハイフンにまとめ、前後のハイフンを落とした小文字文字列を返す。"""
    return _NON_ALNUM.sub("-", text.lower()).strip("-")

